INSERT INTO [titles] ([title_id], [title], [type], [pub_id], [price], [advance], [royalty], [ytd_sales], [notes], [pubdate]) VALUES
(N'BU1032',N'The Busy Executive''s Database Guide',N'business',N'1389',19.99,5000,10,4095,N'An overview of available database systems with emphasis on common business applications. Illustrated.',N'1991-06-12'),
(N'BU1111',N'Cooking with Computers: Surreptitious Balance Sheets',N'business',N'1389',11.95,5000,10,3876,N'Helpful hints on how to use your electronic resources to the best advantage.',N'1991-06-09'),
(N'BU2075',N'You Can Combat Computer Stress!',N'business',N'0736',2.99,10125,24,18722,N'The latest medical and psychological techniques for living with the electronic office. Easy-to-understand explanations.',N'1991-06-30'),
(N'BU7832',N'Straight Talk About Computers',N'business',N'1389',19.99,5000,10,4095,N'Annotated analysis of what computers can do for you: a no-hype guide for the critical user.',N'1991-06-22'),
(N'MC2222',N'Silicon Valley Gastronomic Treats',N'mod_cook',N'0877',19.99,0,12,2032,N'Favorite recipes for quick, easy, and elegant meals.',N'1991-06-09'),
(N'MC3021',N'The Gourmet Microwave',N'mod_cook',N'0877',2.99,15000,24,22246,N'Traditional French gourmet recipes adapted for modern microwave cooking.',N'1991-06-18'),
(N'MC3026',N'The Psychology of Computer Cooking',N'UNDECIDED',N'0877',NULL,NULL,NULL,NULL,NULL,N'2000-01-01'),
(N'PC1035',N'But Is It User Friendly?',N'popular_comp',N'1389',22.95,7000,16,8780,N'A survey of software for the naive user, focusing on the ''friendliness'' of each.',N'1991-06-30'),
(N'PC8888',N'Secrets of Silicon Valley',N'popular_comp',N'1389',20,8000,10,4095,N'Muckraking reporting on the world''s largest computer hardware and software manufacturers.',N'1994-06-12'),
(N'PC9999',N'Net Etiquette',N'popular_comp',N'1389',NULL,NULL,NULL,NULL,N'A must-read for computer conferencing.',N'2000-01-01'),
(N'PS1372',N'Computer Phobic AND Non-Phobic Individuals: Behavior Variations',N'psychology',N'0877',21.59,7000,10,375,N'A must for the specialist, this book examines the difference between those who hate and fear computers and those who don''t.',N'1991-10-21'),
(N'PS2091',N'Is Anger the Enemy?',N'psychology',N'0736',10.95,2275,12,2045,N'Carefully researched study of the effects of strong emotions on the body. Metabolic charts included.',N'1991-06-15'),
(N'PS2106',N'Life Without Fear',N'psychology',N'0736',7,6000,10,111,N'New exercise, meditation, and nutritional techniques that can reduce the shock of daily interactions. Popular audience. Sample menus included, exercise video available separately.',N'1991-10-05'),
(N'PS3333',N'Prolonged Data Deprivation: Four Case Studies',N'psychology',N'0736',19.99,2000,10,4072,N'What happens when the data runs dry?  Searching evaluations of information-shortage effects.',N'1991-06-12'),
(N'PS7777',N'Emotional Security: A New Algorithm',N'psychology',N'0736',7.99,4000,10,3336,N'Protecting yourself and your loved ones from undue emotional stress in the modern world. Use of computer and nutritional aids emphasized.',N'1991-06-12'),
(N'TC3218',N'Onions, Leeks, and Garlic: Cooking Secrets of the Mediterranean',N'trad_cook',N'0877',20.95,7000,10,375,N'Profusely illustrated in color, this makes a wonderful gift book for a cuisine-oriented friend.',N'1991-10-21'),
(N'TC4203',N'Fifty Years in Buckingham Palace Kitchens',N'trad_cook',N'0877',11.95,4000,14,15096,N'More anecdotes from the Queen''s favorite cook describing life among English royalty. Recipes, techniques, tender vignettes.',N'1991-06-12'),
(N'TC7777',N'Sushi, Anyone?',N'trad_cook',N'0877',14.99,8000,10,4095,N'Detailed instructions on how to make authentic Japanese sushi in your spare time.',N'1991-06-12');
